pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 afterDeposit;
        try c.getBalance(address(this)) returns (uint256 __r) { afterDeposit = __r; } catch { return; }
        vm.assume(depositAmount == 0 || afterDeposit == depositAmount);
        vm.assume(address(c).balance >= afterDeposit);
        uint callerBefore = address(this).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 finalBal;
        try c.getBalance(address(this)) returns (uint256 __r) { finalBal = __r; } catch { return; }
        assertTrue(!reverted && finalBal == 0 && address(this).balance == callerBefore + afterDeposit);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
